    #[test]
    fn test_hook_id_to_guid_known_groups() {
        // Process group (0x03), opcode START (1) → hook_id 0x0301 → ProcessGuid
        let guid = hook_id_to_guid(0x0301).unwrap();
        assert_eq!(
            guid,
            crate::Guid::from_u128(0x3d6fa8d0_fe05_11d0_9dda_00c04fd7ba7c)
        );

        // Thread group (0x05), opcode START (1) → hook_id 0x0501 → ThreadGuid
        let guid = hook_id_to_guid(0x0501).unwrap();
        assert_eq!(
            guid,
            crate::Guid::from_u128(0x3d6fa8d1_fe05_11d0_9dda_00c04fd7ba7c)
        );

        // PerfInfo group (0x0F), opcode SAMPLED_PROFILE (46) → hook_id 0x0F2E → PerfInfoGuid
        let guid = hook_id_to_guid(0x0F2E).unwrap();
        assert_eq!(
            guid,
            crate::Guid::from_u128(0xce1dbfb4_137e_4da6_87b0_3f59aa102cbc)
        );
    }

    #[test]
    fn test_hook_id_to_guid_out_of_range() {
        // Group 0x1F is beyond the table
        assert!(hook_id_to_guid(0x1F00).is_none());
        assert!(hook_id_to_guid(0xFF00).is_none());
    }

    #[test]
    fn test_guid_to_group_id_known() {
        // STACKWALK group (0x18) matches STACK_WALK_GUID
        assert_eq!(
            guid_to_group_id(&STACK_WALK_GUID),
            Some(group_id::STACKWALK)
        );
        // Process group (0x03)
        let process_guid = crate::Guid::from_u128(0x3d6fa8d0_fe05_11d0_9dda_00c04fd7ba7c);
        assert_eq!(guid_to_group_id(&process_guid), Some(group_id::PROCESS));
    }

    #[test]
    fn test_guid_to_group_id_unknown() {
        let unknown = crate::Guid::from_u128(0xdeadbeef_dead_beef_dead_beefdeadbeef);
        assert_eq!(guid_to_group_id(&unknown), None);
    }

